<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Result Card</h1><p>Student-wise and class-wise persisted exam results.</p></div><button class="btn btn--primary" onclick="window.print()">Print</button></header><form class="filter-bar filter-bar--compact"><div class="module-field"><label>Exam</label><select class="module-select" name="exam"><option value="">Select Exam</option><?php foreach($exams as$e):?><option value="<?= $e['id'] ?>" <?= $selectedExam==$e['id']?'selected':'' ?>><?= e($e['name']) ?></option><?php endforeach ?></select></div><div class="module-field"><label>Student Wise</label><select class="module-select" name="student"><option value="">None</option><?php foreach($students as$s):?><option value="<?= $s['id'] ?>" <?= $selectedStudent==$s['id']?'selected':'' ?>><?= e($s['registration_no'].' — '.$s['student_name']) ?></option><?php endforeach ?></select></div><div class="module-field"><label>Class Wise</label><select class="module-select" name="class"><option value="">None</option><?php foreach($classes as$c):?><option value="<?= $c['id'] ?>" <?= $selectedClass==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach ?></select></div><button class="btn btn--primary">View</button></form><?php if($result):?><section class="module-card"><div class="module-card__body"><table class="data-table"><thead><tr><th>Subject</th><th>Obtained</th><th>Total</th></tr></thead><tbody><?php foreach($result['subjects']as$x):?><tr><td><?= e($x['subject']) ?></td><td><?= e($x['obtained_marks']) ?></td><td><?= e($x['total_marks']) ?></td></tr><?php endforeach ?></tbody></table><h3><?= number_format($result['percentage'],2) ?>% · Grade <?= e($result['grade']['grade']??'—') ?> · <?= e($result['grade']['status']??'Not configured') ?></h3></div></section><?php endif ?><?php if($rows):?><section class="module-card"><div class="module-card__body"><table class="data-table"><thead><tr><th>Registration</th><th>Student</th><th>Obtained</th><th>Total</th><th>%</th></tr></thead><tbody><?php foreach($rows as$x):?><tr><td><?= e($x['registration_no']) ?></td><td><?= e($x['student_name']) ?></td><?php $abs=(int)($x['absent_subjects']??0); $allAbs=$abs>0&&$abs===(int)$x['subjects']; ?><td><?= $allAbs?'<span class="status-badge status-badge--absent">Absent</span>':e($x['obtained']??0).($abs?' <span class="status-badge status-badge--absent">Absent in '.$abs.'</span>':'') ?></td><td><?= e($x['total']) ?></td><td><?= $allAbs?'—':e($x['percentage']??0) ?></td></tr><?php endforeach ?></tbody></table></div></section><?php endif ?></div></div></main>
